INSERT INTO jarvis_ops.tool_registry (tool_id, version, adapter_id, operation, external_effect, risk_class_default, reversibility, undo_tool_id, allowed_contexts, readback_supported, accepted_methods, evidence_limitation, timeout_seconds, dry_run_supported, status, definition, definition_sha256, source_file, source_sha256) VALUES ('tasks_internal.create_task', '1.0.0', 'tasks_internal', 'write', 'internal', 'A', 'reversible', 'tasks_internal.cancel_task', ARRAY['privat', 'arbeitgeber_visolva']::text[], true, ARRAY['readback']::text[], NULL, 30, true, 'draft', '{"owner": "rolf", "purpose": "Aufgabe im JARVIS-Aufgabenregister anlegen.", "tool_id": "tasks_internal.create_task", "version": "1.0.0", "evidence": {"limitation": null, "required_types": ["task_ref"], "accepted_methods": ["readback"], "readback_supported": true, "verify_delay_seconds": 0, "deferred_check_after_hours": null}, "operation": "write", "adapter_id": "tasks_internal", "rate_limit": null, "idempotency": {"strategy": "db_unique_constraint", "key_fields": ["context_id", "source_ref", "action_type", "target_system", "target_object_ref"], "extra_dedup": null, "native_support": false}, "display_name": "Aufgabe anlegen", "retry_policy": {"backoff": "exponential_1m_factor5_jitter", "max_attempts": 3, "retryable_error_classes": ["transient_network", "timeout"]}, "side_effects": "Ein neuer Aufgabendatensatz entsteht.", "undo_tool_id": "tasks_internal.cancel_task", "reversibility": "reversible", "external_effect": "internal", "timeout_seconds": 30, "allowed_contexts": ["privat", "arbeitgeber_visolva"], "input_schema_ref": "schemas/task.schema.json", "dry_run_supported": true, "output_schema_ref": "schemas/task.schema.json", "risk_class_default": "A", "required_permissions": ["Schreibrecht im Kontextschema"]}'::jsonb, '7f7ffd57979954afa94bb742f3958c65f7f9e46067d2b00907c02160e40fd1ac', 'spec/phase-0/jarvis-phase-0/registry/tool_registry.json', 'b97208de94bbedfc0b00ef8e99ba749cabd766e6f85f48e6a933dc972761e613') ON CONFLICT (tool_id, version) DO NOTHING;
INSERT INTO jarvis_ops.tool_registry (tool_id, version, adapter_id, operation, external_effect, risk_class_default, reversibility, undo_tool_id, allowed_contexts, readback_supported, accepted_methods, evidence_limitation, timeout_seconds, dry_run_supported, status, definition, definition_sha256, source_file, source_sha256) VALUES ('mail_default.send_message', '1.0.0', 'mail_default', 'write', 'external_recipient', 'C', 'irreversible', NULL, ARRAY['privat', 'arbeitgeber_visolva']::text[], true, ARRAY['readback']::text[], NULL, 60, true, 'draft', '{"owner": "rolf", "purpose": "Individuelle oder freigegebene E-Mail versenden.", "tool_id": "mail_default.send_message", "version": "1.0.0", "evidence": {"limitation": null, "required_types": ["message_ref"], "accepted_methods": ["readback"], "readback_supported": true, "verify_delay_seconds": 15, "deferred_check_after_hours": null}, "operation": "write", "adapter_id": "mail_default", "rate_limit": null, "idempotency": {"strategy": "db_plus_provider", "key_fields": ["context_id", "source_ref", "action_type", "target_system", "target_object_ref"], "extra_dedup": "content_fingerprint", "native_support": false}, "display_name": "E-Mail versenden", "retry_policy": {"backoff": "exponential_1m_factor5_jitter", "max_attempts": 3, "retryable_error_classes": ["transient_network", "timeout", "rate_limited"]}, "side_effects": "Eine Nachricht verlaesst das System und erreicht einen externen Empfaenger.", "undo_tool_id": null, "reversibility": "irreversible", "external_effect": "external_recipient", "timeout_seconds": 60, "allowed_contexts": ["privat", "arbeitgeber_visolva"], "input_schema_ref": "schemas/tools/mail_default.send_message.input.json", "dry_run_supported": true, "output_schema_ref": "schemas/tools/mail_default.send_message.output.json", "risk_class_default": "C", "required_permissions": ["Nachricht senden", "Ordner Gesendet lesen"]}'::jsonb, 'bddb2305ff17cf0f5f470d597ffd2fb8ac6e73f339655477525fc0effa50c4ea', 'spec/phase-0/jarvis-phase-0/registry/tool_registry.json', 'b97208de94bbedfc0b00ef8e99ba749cabd766e6f85f48e6a933dc972761e613') ON CONFLICT (tool_id, version) DO NOTHING;
INSERT INTO jarvis_ops.tool_registry (tool_id, version, adapter_id, operation, external_effect, risk_class_default, reversibility, undo_tool_id, allowed_contexts, readback_supported, accepted_methods, evidence_limitation, timeout_seconds, dry_run_supported, status, definition, definition_sha256, source_file, source_sha256) VALUES ('messaging_superchat.send_template_message', '1.0.0', 'messaging_superchat', 'write', 'external_recipient', 'B', 'irreversible', NULL, ARRAY['arbeitgeber_visolva']::text[], false, ARRAY['provider_message_id', 'delivery_receipt', 'recipient_reply']::text[], 'Der Anbieter stellt keinen Lesezugriff auf die versendete Nachricht bereit. Die Anbieter-ID belegt die Annahme des Auftrags und die Zustellquittung die Auslieferung an das Endgeraet, nicht jedoch, dass der Empfaenger die Nachricht gelesen oder inhaltlich verstanden hat.', 45, false, 'draft', '{"owner": "rolf", "purpose": "Freigegebene Standardnachricht ueber den Messenger-Kanal senden.", "tool_id": "messaging_superchat.send_template_message", "version": "1.0.0", "evidence": {"limitation": "Der Anbieter stellt keinen Lesezugriff auf die versendete Nachricht bereit. Die Anbieter-ID belegt die Annahme des Auftrags und die Zustellquittung die Auslieferung an das Endgeraet, nicht jedoch, dass der Empfaenger die Nachricht gelesen oder inhaltlich verstanden hat.", "required_types": ["provider_id", "delivery_receipt"], "accepted_methods": ["provider_message_id", "delivery_receipt", "recipient_reply"], "readback_supported": false, "verify_delay_seconds": 30, "deferred_check_after_hours": 24}, "operation": "write", "adapter_id": "messaging_superchat", "rate_limit": "60/Stunde", "idempotency": {"strategy": "db_plus_provider", "key_fields": ["context_id", "source_ref", "action_type", "target_system", "target_object_ref"], "extra_dedup": "content_fingerprint", "native_support": true}, "display_name": "Standardnachricht ueber Messenger senden", "retry_policy": {"backoff": "exponential_1m_factor5_jitter", "max_attempts": 3, "retryable_error_classes": ["transient_network", "timeout", "rate_limited"]}, "side_effects": "Eine Nachricht wird an den Anbieter uebergeben und an einen externen Empfaenger zugestellt.", "undo_tool_id": null, "reversibility": "irreversible", "external_effect": "external_recipient", "timeout_seconds": 45, "allowed_contexts": ["arbeitgeber_visolva"], "input_schema_ref": "schemas/tools/messaging_superchat.send_template_message.input.json", "dry_run_supported": false, "output_schema_ref": "schemas/tools/messaging_superchat.send_template_message.output.json", "risk_class_default": "B", "required_permissions": ["Nachricht senden"]}'::jsonb, '8cded196683889056b0a0fe4e8e52cfedfe16d6e1dca10f820ecdf9e4694caec', 'spec/phase-0/jarvis-phase-0/registry/tool_registry.json', 'b97208de94bbedfc0b00ef8e99ba749cabd766e6f85f48e6a933dc972761e613') ON CONFLICT (tool_id, version) DO NOTHING;
INSERT INTO jarvis_ops.tool_registry (tool_id, version, adapter_id, operation, external_effect, risk_class_default, reversibility, undo_tool_id, allowed_contexts, readback_supported, accepted_methods, evidence_limitation, timeout_seconds, dry_run_supported, status, definition, definition_sha256, source_file, source_sha256) VALUES ('approval_email.request_decision', '1.0.0', 'approval_email', 'write', 'internal', 'A', 'reversible', 'approval_email.revoke_request', ARRAY['privat', 'arbeitgeber_visolva']::text[], true, ARRAY['readback']::text[], NULL, 30, true, 'draft', '{"owner": "rolf", "purpose": "Freigabeanforderung mit signiertem Einmal-Link an Rolf senden.", "tool_id": "approval_email.request_decision", "version": "1.0.0", "evidence": {"limitation": null, "required_types": ["message_ref"], "accepted_methods": ["readback"], "readback_supported": true, "verify_delay_seconds": 15, "deferred_check_after_hours": null}, "operation": "write", "adapter_id": "approval_email", "rate_limit": null, "idempotency": {"strategy": "db_unique_constraint", "key_fields": ["context_id", "source_ref", "action_type", "target_system", "target_object_ref"], "extra_dedup": "action_fingerprint", "native_support": false}, "display_name": "Freigabe anfordern", "retry_policy": {"backoff": "exponential_1m_factor5_jitter", "max_attempts": 3, "retryable_error_classes": ["transient_network", "timeout"]}, "side_effects": "Rolf erhaelt eine Entscheidungsanfrage. Die freizugebende Aktion selbst bleibt unveraendert.", "undo_tool_id": "approval_email.revoke_request", "reversibility": "reversible", "external_effect": "internal", "timeout_seconds": 30, "allowed_contexts": ["privat", "arbeitgeber_visolva"], "input_schema_ref": "schemas/approval.schema.json", "dry_run_supported": true, "output_schema_ref": "schemas/approval.schema.json", "risk_class_default": "A", "required_permissions": ["Nachricht senden", "Ordner Gesendet lesen"]}'::jsonb, 'd259ab39ff01de0aa7a67f0f1ef4e6c48fceb5c8bc8af4ccb6b14ee5c5e8fc6d', 'spec/phase-0/jarvis-phase-0/registry/tool_registry.json', 'b97208de94bbedfc0b00ef8e99ba749cabd766e6f85f48e6a933dc972761e613') ON CONFLICT (tool_id, version) DO NOTHING;
INSERT INTO jarvis_ops.tool_registry (tool_id, version, adapter_id, operation, external_effect, risk_class_default, reversibility, undo_tool_id, allowed_contexts, readback_supported, accepted_methods, evidence_limitation, timeout_seconds, dry_run_supported, status, definition, definition_sha256, source_file, source_sha256) VALUES ('storage_gdrive.get_file', '1.0.0', 'storage_gdrive', 'read', 'none', 'A', 'reversible', NULL, ARRAY['privat', 'arbeitgeber_visolva']::text[], false, ARRAY['provider_status']::text[], 'Leseoperation ohne Zustandsaenderung. Der Nachweis belegt die erfolgreiche Antwort des Speicherdienstes einschliesslich Pruefsumme, nicht eine Veraenderung in der Welt.', 120, true, 'draft', '{"owner": "rolf", "purpose": "Originaldatei und ihre Metadaten aus dem kontextbezogenen Speicher lesen.", "tool_id": "storage_gdrive.get_file", "version": "1.0.0", "evidence": {"limitation": "Leseoperation ohne Zustandsaenderung. Der Nachweis belegt die erfolgreiche Antwort des Speicherdienstes einschliesslich Pruefsumme, nicht eine Veraenderung in der Welt.", "required_types": ["provider_status"], "accepted_methods": ["provider_status"], "readback_supported": false, "verify_delay_seconds": 0, "deferred_check_after_hours": null}, "operation": "read", "adapter_id": "storage_gdrive", "rate_limit": null, "idempotency": {"strategy": "db_unique_constraint", "key_fields": ["context_id", "source_ref", "action_type", "target_system", "target_object_ref"], "extra_dedup": null, "native_support": false}, "display_name": "Datei lesen", "retry_policy": {"backoff": "exponential_1m_factor5_jitter", "max_attempts": 3, "retryable_error_classes": ["transient_network", "rate_limited", "timeout"]}, "side_effects": "Keine. Reine Leseoperation.", "undo_tool_id": null, "reversibility": "reversible", "external_effect": "none", "timeout_seconds": 120, "allowed_contexts": ["privat", "arbeitgeber_visolva"], "input_schema_ref": "schemas/tools/storage_gdrive.get_file.input.json", "dry_run_supported": true, "output_schema_ref": "schemas/tools/storage_gdrive.get_file.output.json", "risk_class_default": "A", "required_permissions": ["Datei lesen", "Metadaten lesen"]}'::jsonb, '02372a67f50f263bd052c2e6ccc96b7e4853c49b290a95a3b7a3eed16717561b', 'spec/phase-1/jarvis-phase-1/registry/tool_registry_phase1.json', '2aea6dc8246e518e070f91480e890c2b7d76d538e6a6420ae4c5e1f3667d3621') ON CONFLICT (tool_id, version) DO NOTHING;
INSERT INTO jarvis_ops.tool_registry (tool_id, version, adapter_id, operation, external_effect, risk_class_default, reversibility, undo_tool_id, allowed_contexts, readback_supported, accepted_methods, evidence_limitation, timeout_seconds, dry_run_supported, status, definition, definition_sha256, source_file, source_sha256) VALUES ('ocr_default.analyze_document', '1.0.0', 'ocr_default', 'read', 'none', 'A', 'reversible', NULL, ARRAY['privat', 'arbeitgeber_visolva']::text[], false, ARRAY['provider_status']::text[], 'Der Nachweis belegt, dass der Dienst ein Ergebnis zum uebermittelten Inhaltshash geliefert hat. Er belegt nicht die inhaltliche Richtigkeit der Texterkennung; diese wird ueber Konfidenz- und Feldregeln bewertet.', 300, false, 'draft', '{"owner": "rolf", "purpose": "Volltext, Seitenstruktur, Tabellen und Feldkandidaten mit Konfidenz und Positionsbezug erfassen.", "tool_id": "ocr_default.analyze_document", "version": "1.0.0", "evidence": {"limitation": "Der Nachweis belegt, dass der Dienst ein Ergebnis zum uebermittelten Inhaltshash geliefert hat. Er belegt nicht die inhaltliche Richtigkeit der Texterkennung; diese wird ueber Konfidenz- und Feldregeln bewertet.", "required_types": ["provider_status", "content_hash"], "accepted_methods": ["provider_status"], "readback_supported": false, "verify_delay_seconds": 0, "deferred_check_after_hours": null}, "operation": "read", "adapter_id": "ocr_default", "rate_limit": "600/Stunde", "idempotency": {"strategy": "db_unique_constraint", "key_fields": ["context_id", "source_ref", "action_type", "target_system", "target_object_ref"], "extra_dedup": "content_hash", "native_support": false}, "display_name": "Dokument technisch erfassen", "retry_policy": {"backoff": "exponential_1m_factor5_jitter", "max_attempts": 3, "retryable_error_classes": ["transient_network", "rate_limited", "timeout", "dependency_unavailable"]}, "side_effects": "Das Dokument wird an einen externen Analysedienst uebermittelt. Es entsteht keine Veraenderung im Quellsystem.", "undo_tool_id": null, "reversibility": "reversible", "external_effect": "none", "timeout_seconds": 300, "allowed_contexts": ["privat", "arbeitgeber_visolva"], "input_schema_ref": "schemas/tools/ocr_default.analyze_document.input.json", "dry_run_supported": false, "output_schema_ref": "schemas/tools/ocr_default.analyze_document.output.json", "risk_class_default": "A", "required_permissions": ["Dokument zur Analyse uebermitteln"]}'::jsonb, '02ec67aa1dd8b3d81ee1f11c0eb2952654f64eb87003a35f3f0ab3bd726e7b78', 'spec/phase-1/jarvis-phase-1/registry/tool_registry_phase1.json', '2aea6dc8246e518e070f91480e890c2b7d76d538e6a6420ae4c5e1f3667d3621') ON CONFLICT (tool_id, version) DO NOTHING;
INSERT INTO jarvis_ops.tool_registry (tool_id, version, adapter_id, operation, external_effect, risk_class_default, reversibility, undo_tool_id, allowed_contexts, readback_supported, accepted_methods, evidence_limitation, timeout_seconds, dry_run_supported, status, definition, definition_sha256, source_file, source_sha256) VALUES ('llm_default.extract_fields', '1.0.0', 'llm_default', 'read', 'none', 'A', 'reversible', NULL, ARRAY['privat', 'arbeitgeber_visolva']::text[], false, ARRAY['provider_status']::text[], 'Der Nachweis belegt eine schemakonforme Modellantwort. Die fachliche Richtigkeit der Werte wird nicht belegt und ausschliesslich ueber Konfidenz-, Beleg- und Plausibilitaetsregeln bewertet.', 180, false, 'draft', '{"owner": "rolf", "purpose": "Aus Volltext und OCR-Kandidaten die Pflicht- und Zusatzfelder mit Konfidenz und Textbeleg gewinnen.", "tool_id": "llm_default.extract_fields", "version": "1.0.0", "evidence": {"limitation": "Der Nachweis belegt eine schemakonforme Modellantwort. Die fachliche Richtigkeit der Werte wird nicht belegt und ausschliesslich ueber Konfidenz-, Beleg- und Plausibilitaetsregeln bewertet.", "required_types": ["provider_status"], "accepted_methods": ["provider_status"], "readback_supported": false, "verify_delay_seconds": 0, "deferred_check_after_hours": null}, "operation": "read", "adapter_id": "llm_default", "rate_limit": null, "idempotency": {"strategy": "db_unique_constraint", "key_fields": ["context_id", "source_ref", "action_type", "target_system", "target_object_ref"], "extra_dedup": null, "native_support": false}, "display_name": "Felder auslesen", "retry_policy": {"backoff": "exponential_1m_factor5_jitter", "max_attempts": 3, "retryable_error_classes": ["transient_network", "rate_limited", "timeout", "validation_error"]}, "side_effects": "Keine Veraenderung ausserhalb von JARVIS.", "undo_tool_id": null, "reversibility": "reversible", "external_effect": "none", "timeout_seconds": 180, "allowed_contexts": ["privat", "arbeitgeber_visolva"], "input_schema_ref": "schemas/tools/llm_default.extract_fields.input.json", "dry_run_supported": false, "output_schema_ref": "schemas/extraction_result.schema.json", "risk_class_default": "A", "required_permissions": ["Modellaufruf mit strukturierter Ausgabe"]}'::jsonb, '04d8785d8a7a1c23f93a16793dc86ed204db8e1cd05df88e3cbd09ed8f6626d6', 'spec/phase-1/jarvis-phase-1/registry/tool_registry_phase1.json', '2aea6dc8246e518e070f91480e890c2b7d76d538e6a6420ae4c5e1f3667d3621') ON CONFLICT (tool_id, version) DO NOTHING;
INSERT INTO jarvis_ops.tool_registry (tool_id, version, adapter_id, operation, external_effect, risk_class_default, reversibility, undo_tool_id, allowed_contexts, readback_supported, accepted_methods, evidence_limitation, timeout_seconds, dry_run_supported, status, definition, definition_sha256, source_file, source_sha256) VALUES ('llm_default.analyze_document', '1.0.0', 'llm_default', 'read', 'none', 'A', 'reversible', NULL, ARRAY['privat', 'arbeitgeber_visolva']::text[], false, ARRAY['provider_status']::text[], 'Der Nachweis belegt eine schemakonforme Modellantwort mit Textbelegen. Er belegt weder die Vollstaendigkeit der erkannten Verpflichtungen noch die Richtigkeit der Vorschlaege.', 240, false, 'draft', '{"owner": "rolf", "purpose": "Sachverhalt, Verpflichtungen, Moeglichkeiten, Risiken, Widersprueche, fehlende Angaben und Aufgabenvorschlaege bestimmen.", "tool_id": "llm_default.analyze_document", "version": "1.0.0", "evidence": {"limitation": "Der Nachweis belegt eine schemakonforme Modellantwort mit Textbelegen. Er belegt weder die Vollstaendigkeit der erkannten Verpflichtungen noch die Richtigkeit der Vorschlaege.", "required_types": ["provider_status"], "accepted_methods": ["provider_status"], "readback_supported": false, "verify_delay_seconds": 0, "deferred_check_after_hours": null}, "operation": "read", "adapter_id": "llm_default", "rate_limit": null, "idempotency": {"strategy": "db_unique_constraint", "key_fields": ["context_id", "source_ref", "action_type", "target_system", "target_object_ref"], "extra_dedup": null, "native_support": false}, "display_name": "Dokument verstehen", "retry_policy": {"backoff": "exponential_1m_factor5_jitter", "max_attempts": 3, "retryable_error_classes": ["transient_network", "rate_limited", "timeout", "validation_error"]}, "side_effects": "Keine Veraenderung ausserhalb von JARVIS.", "undo_tool_id": null, "reversibility": "reversible", "external_effect": "none", "timeout_seconds": 240, "allowed_contexts": ["privat", "arbeitgeber_visolva"], "input_schema_ref": "schemas/tools/llm_default.analyze_document.input.json", "dry_run_supported": false, "output_schema_ref": "schemas/document_analysis.schema.json", "risk_class_default": "A", "required_permissions": ["Modellaufruf mit strukturierter Ausgabe"]}'::jsonb, '3d268e8a4d890ceda898ce6751b2508c73b37bee49da7c4b8fbc492c852d0617', 'spec/phase-1/jarvis-phase-1/registry/tool_registry_phase1.json', '2aea6dc8246e518e070f91480e890c2b7d76d538e6a6420ae4c5e1f3667d3621') ON CONFLICT (tool_id, version) DO NOTHING;
INSERT INTO jarvis_ops.tool_registry (tool_id, version, adapter_id, operation, external_effect, risk_class_default, reversibility, undo_tool_id, allowed_contexts, readback_supported, accepted_methods, evidence_limitation, timeout_seconds, dry_run_supported, status, definition, definition_sha256, source_file, source_sha256) VALUES ('docstore_internal.upsert_document', '1.0.0', 'docstore_internal', 'write', 'internal', 'A', 'reversible', NULL, ARRAY['privat', 'arbeitgeber_visolva']::text[], true, ARRAY['readback']::text[], NULL, 30, true, 'draft', '{"owner": "rolf", "purpose": "Dokumentdatensatz im Kontextschema anlegen oder fortschreiben.", "tool_id": "docstore_internal.upsert_document", "version": "1.0.0", "evidence": {"limitation": null, "required_types": ["state_readback"], "accepted_methods": ["readback"], "readback_supported": true, "verify_delay_seconds": 0, "deferred_check_after_hours": null}, "operation": "write", "adapter_id": "docstore_internal", "rate_limit": null, "idempotency": {"strategy": "db_unique_constraint", "key_fields": ["context_id", "source_ref", "action_type", "target_system", "target_object_ref"], "extra_dedup": "content_hash", "native_support": true}, "display_name": "Dokumentregister schreiben", "retry_policy": {"backoff": "exponential_1m_factor5_jitter", "max_attempts": 3, "retryable_error_classes": ["transient_network", "timeout"]}, "side_effects": "Ein Dokumentdatensatz entsteht oder aendert seinen Zustand.", "undo_tool_id": null, "reversibility": "reversible", "external_effect": "internal", "timeout_seconds": 30, "allowed_contexts": ["privat", "arbeitgeber_visolva"], "input_schema_ref": "schemas/document.schema.json", "dry_run_supported": true, "output_schema_ref": "schemas/document.schema.json", "risk_class_default": "A", "required_permissions": ["Schreibrecht im Kontextschema"]}'::jsonb, '22653a59c5f22a552cbb4804b809a9b003bc093a00de2cfd86d18c2c419c53c9', 'spec/phase-1/jarvis-phase-1/registry/tool_registry_phase1.json', '2aea6dc8246e51